.vmz-gate {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(15, 23, 42, 0.72);
  overscroll-behavior: contain;
  font-family: 'Inter', 'Helvetica Neue', Arial, system-ui, sans-serif;
  color: #1f2937;
  text-align: left;
  -webkit-font-smoothing: antialiased;
}
.vmz-gate.vmz-gate,
.vmz-gate.vmz-gate * {
  border-radius: 0 !important;
}
.vmz-gate .vmz-gate-dialog {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 680px;
  max-height: calc(100vh - 32px);
  max-height: calc(100dvh - 32px);
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px !important;
  box-shadow: 0 24px 64px rgba(15, 23, 42, 0.35);
}
.vmz-gate .vmz-gate-dialog:focus {
  outline: none;
}
.vmz-gate .vmz-gate-head {
  flex: none;
  padding: 22px 24px 16px;
  border-bottom: 1px solid #e2e8f0;
}
.vmz-gate .vmz-gate-eyebrow {
  margin: 0 0 6px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #1f5e96;
}
.vmz-gate .vmz-gate-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
  color: #0f172a !important;
}
.vmz-gate .vmz-gate-intro {
  margin: 8px 0 0;
  font-size: 14px;
  line-height: 1.55;
  color: #475569;
}
.vmz-gate .vmz-gate-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 20px 24px 8px;
}
.vmz-gate .vmz-gate-section + .vmz-gate-section {
  margin-top: 20px;
}
.vmz-gate .vmz-gate-section-title {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1.4;
  color: #1f5e96 !important;
}
.vmz-gate .vmz-gate-section-text {
  margin: 0;
  font-size: 15px;
  line-height: 1.65;
  color: #1f2937;
  white-space: pre-line;
  overflow-wrap: break-word;
}
.vmz-gate .vmz-gate-copyright {
  margin: 24px 0 12px;
  font-size: 13px;
  text-align: center;
  color: #64748b;
}
.vmz-gate .vmz-gate-foot {
  flex: none;
  padding: 16px 24px 20px;
  border-top: 1px solid #e2e8f0;
  background: #f8fafc;
}
.vmz-gate .vmz-gate-consent {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 8px !important;
  background: #ffffff;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.5;
  color: #0f172a;
  cursor: pointer;
}
.vmz-gate .vmz-gate-consent:hover,
.vmz-gate .vmz-gate-consent-checked {
  border-color: #1f5e96;
}
.vmz-gate .vmz-gate-consent-checked {
  background: #e6eef5;
}
.vmz-gate .vmz-gate-checkbox {
  flex: none;
  width: 18px;
  height: 18px;
  margin: 2px 0 0;
  accent-color: #1f5e96;
  cursor: pointer;
}
.vmz-gate .vmz-gate-checkbox:focus {
  box-shadow: none !important;
}
.vmz-gate .vmz-gate-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 14px;
}
.vmz-gate .vmz-gate-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 10px 20px;
  border: 1px solid transparent;
  border-radius: 8px !important;
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.2;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
.vmz-gate .vmz-gate-btn-secondary {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #334155;
}
.vmz-gate .vmz-gate-btn-secondary:hover {
  background: #f1f5f9;
  border-color: #94a3b8;
}
.vmz-gate .vmz-gate-btn-primary {
  background: #1f5e96;
  border-color: #1f5e96;
  color: #ffffff;
}
.vmz-gate .vmz-gate-btn-primary:hover:not(:disabled) {
  background: #184b78;
  border-color: #184b78;
}
/* Pending state: the button is disabled until the attestation is ticked. It
   must still read as a real control with a reason, so the text keeps >= 4.5:1
   (#3f4f5d on #e6eef5 = 6.9:1), the border stays visible, and a hint beside
   the buttons says what unlocks it. */
.vmz-gate .vmz-gate-btn-primary:disabled {
  background: #e6eef5;
  border-color: #b9c6d2;
  color: #3f4f5d;
  cursor: not-allowed;
}
.vmz-gate .vmz-gate-hint {
  flex: 1 1 100%;
  margin: 0;
  font-size: 13px;
  line-height: 1.4;
  color: #7a4e00;
}
.vmz-gate .vmz-gate-hint[hidden] { display: none; }
.vmz-gate .vmz-gate-btn:focus-visible,
.vmz-gate .vmz-gate-checkbox:focus-visible,
.vmz-gate .vmz-gate-body a:focus-visible {
  outline: 3px solid #b45309 !important;
  outline-offset: 2px !important;
}
.vmz-gate .vmz-gate-body:focus-visible {
  outline: 3px solid #b45309 !important;
  outline-offset: -3px;
}
@media (max-width: 520px) {
  .vmz-gate { padding: 8px; }
  .vmz-gate .vmz-gate-dialog {
    max-height: calc(100vh - 16px);
    max-height: calc(100dvh - 16px);
  }
  .vmz-gate .vmz-gate-head { padding: 16px 16px 12px; }
  .vmz-gate .vmz-gate-title { font-size: 18px; }
  .vmz-gate .vmz-gate-body { padding: 16px 16px 4px; }
  .vmz-gate .vmz-gate-foot { padding: 12px 16px 16px; }
  .vmz-gate .vmz-gate-btn { flex: 1 1 auto; }
}
/* Very short screens (e.g. a phone turned sideways): scroll the whole dialog
   as one so the legal text area never collapses to nothing. */
@media (max-height: 560px) {
  .vmz-gate .vmz-gate-dialog { overflow-y: auto; }
  .vmz-gate .vmz-gate-body { flex: none; min-height: auto; overflow: visible; }
}
@media (prefers-reduced-motion: reduce) {
  .vmz-gate .vmz-gate-btn { transition: none; }
}

